.asideNavBar {
  position: relative;

  .aside-content {
    position: fixed;
    height: 100%;
    width: 300px;
    right: -300px;
    top: 0;
    border: none;
    border-radius: 0;
    background: #ffffff;
    transition: left 500ms linear;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
    z-index: 9;

    .card-title {
      cursor: pointer;
    }
  }

  &.active .aside-content {
    right: 0;
  }

  &.active .overlay {
    position: fixed;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    background-color: hsla(0, 0%, 100%, 0.1);
    z-index: 9;
    cursor: pointer;
    user-select: none;
  }
}

.bookmarks_section {
  .type-wise-list {
    a {
      text-decoration: none;
      color: #212529;
    }
  }

  .singlecard {
    height: 80px;
    position: relative;
    border-radius: 6px;
    overflow: hidden;
    flex-direction: row;
    margin-bottom: 1rem;
    text-decoration: none;

    &::before {
      background: hsla(0, 0%, 0%, 0.6);
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      content: "";
      position: absolute;
      z-index: 1;
    }

    .bg-img {
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      content: "";
      position: absolute;
      z-index: 1;
      background-size: cover;
      background-position: top center;
      background-repeat: no-repeat;
      filter: blur(2px);
    }

    .content {
      color: #ffffff;
      position: relative;
      z-index: 2;

      .icon {
        text-align: center;
        display: block;
        line-height: 60px;
        width: 60px;
        height: 60px;
        border-radius: 4px;
        // background: hsla(0, 0%, 0%, 0.7);
        color: #ffffff;

        svg {
          height: 45px;
        }
      }
    }
  }
  
  .tags-list {
    margin: 0;
    padding: 0;

    li {
      font-size: 13px;
      padding: 0.2rem 1rem;
      margin-bottom: 10px;
      border-radius: 30px;
      background: #e0e0e0;

      a {
        color: #212529;
        text-decoration: none;
      }
    }
  }
}

.bookmark-header {
  position: relative;
  padding: 25px 0 5px;
  color: #ffffff;
  background: #00a881;
  box-shadow: 0px 3px 16px #00000029 !important;

  form.top_header .css-2b097c-container {
    .css-26l3qy-menu {
      color: #212529;
    }
  }

  &.chemistry {
    background: #0060ce;
  }

  &.physics {
    background: #feaf55;
  }

  &.botany {
    background: #3d8815;
  }

  &.zoology {
    background: #c37800;
  }

  &.maths {
    background: #707070;
  }
}

.bookmarks_videos {
  position: relative;

  a {
    text-decoration: none;
    color: #212529;
  }

  .card {
    overflow: hidden;
    border-radius: 6px;

    .bg-blur {
      background: hsla(0, 0%, 0%, 0.5) !important;
    }

    .content {
      position: absolute;
      background: hsla(0, 0%, 100%, 0.5);
      width: 100%;
      bottom: 0;
      left: 0;

      .card-title {
        font-size: 15px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        margin-bottom: 0;
      }

      .d-flex .videodurations {
        padding: 2px 4px;
        background: hsla(0, 0%, 0%, 0.4);
        border-radius: 6px 0;
      }
    }
  }
}

.bookmark_shortNote_materials {
  .bookmark_shortNotes_navs {
    .nav-item .nav-link {
      color: #121412;
      font-weight: 400;
      padding: 0.5rem 1rem 1rem;

      &.active {
        font-weight: 600;
        color: #007bff;
      }
    }
  }

  .section-description {
    // background-color: #e9ecef;

    .breadcrumb-content {
      .breadcrumb {
        background: transparent !important;
      }
    }
  }

  .shortnote_cards {
    margin: 0;

    li.single_shortnote_list {
      margin-bottom: 20px;

      &:last-child {
        margin-bottom: 0;
      }

      a {
        text-decoration: none;
        color: #121412;
      }

      .single_card {
        .card-body {
          overflow: hidden;
          position: relative;
          height: 90px;
          margin-bottom: 15px;
        }

        &.fullView {
          .card-body {
            height: 100%;
          }
        }

        .helpTags li.list-inline-item {
          cursor: pointer;
          color: #00000082;
        }
      }
    }

    .notesTags .card {
      cursor: pointer;
    }
  }

  .material_cards {
    a {
      text-decoration: none;
      color: #121412;
    }

    .single_material_list {
      position: relative;
      margin-bottom: 20px;

      &:last-child {
        margin-bottom: 0;
      }

      .single_card {
        .helpTags li.list-inline-item {
          cursor: pointer;
          color: #00000082;
        }
      }
    }
  }

  #filter-popover.popover {
    max-width: 300px !important;

    @media (max-width: 991px) {
      .card-group .card + .card {
        border-left: 1px solid rgba(0, 0, 0, 0.125) !important;
      }
    }

    @media (max-width: 991px) {
      .card-group {
        display: flex;
        flex-flow: column wrap;

        .card {
          flex-direction: inherit;
          margin-bottom: 15px;
        }
      }
    }

    .popover-body {
      padding: 0;

      .nav-tabs {
        background: #f8f9fa;
        border-top-left-radius: 0.25rem;
        border-top-right-radius: 0.25rem;
      }

      .nav-tabs .nav-item {
        margin-bottom: 0;

        .nav-link {
          border: none;
        }
      }

      .nav-tabs .nav-link {
        font-weight: 500;
        border: none;
        color: #495057;
      }

      .nav-tabs .nav-link.active,
      .nav-tabs .nav-item.show .nav-link {
        font-weight: 600;
        color: #121412;
        background-color: #f8f9fa;
        border-bottom: 2px solid #3ac555;
      }

      .tab-content {
        padding: 0.5rem 0.5rem 0;
        max-height: 130px;
        overflow-y: scroll;

        .custom-list li {
          margin-bottom: 6px;

          &:not(:last-child) {
            margin-right: 0;
          }

          .text {
            width: 250px;
            line-height: 20px;
          }
        }
      }
    }
  }
}

.practice_questions {
  position: relative;

  .questions-list li {
    margin-bottom: 10px;

    &:last-child {
      margin-bottom: 0;
    }

    a {
      position: relative;
      text-decoration: none;
      color: #212529;

      .single_question {
        margin-right: 10px;
      }

      &:hover {
        background-color: #ffffff;
      }

      &.active {
        .single_question {
          margin-right: 0px;
        }
      }

      @media (max-width: 991px) {
        &.active {
          .single_question {
            margin-right: 10px;
          }
        }
      }
    }

    .single_question {
      .srNo {
        font-size: 14px;
        padding: 0.6rem;
        border-radius: 4px;
        text-align: center;
        border: 1px solid #dfdfdf;
        color: #3ac555;
        margin-right: 10px;
      }

      .question-content {
        height: 50px;
        overflow: hidden;
      }
    }
  }

  .note-list .card {
    cursor: pointer;
  }
}

.page-indication {
  .nav .nav-item {
    margin-right: 4px;

    &:last-child {
      margin-right: 0;
    }

    &:nth-child(1) .nav-link.active {
      color: #ffffff;
      background: hsla(211, 100%, 50%, 1);
      border: 1px solid hsla(211, 100%, 50%, 0.6);
    }

    &:nth-child(2) .nav-link.active {
      color: #ffffff;
      background: hsla(134, 61%, 41%, 1);
      border: 1px solid hsla(134, 61%, 41%, 0.6);
    }

    &:nth-child(3) .nav-link.active {
      color: #ffffff;
      background: hsla(45, 100%, 51%, 1);
      border: 1px solid hsla(45, 100%, 51%, 0.6);
    }

    &:nth-child(4) .nav-link.active {
      color: #ffffff;
      background: hsla(354, 70%, 54%, 1);
      border: 1px solid hsla(354, 70%, 54%, 0.6);
    }

    .nav-link {
      color: #121412;
      border-radius: 1.5rem;
      border: 1px solid #dfe0e1;
      padding: 0.5rem 1rem;
      transition: 0.3s all;
    }
  }
}

.sr-tags-list {
  position: relative;
   li {
    font-size: 12px;
    padding: 0.1rem 1rem;
    margin-bottom: 10px;
    border-radius: 30px;
    background: #e0e0e0;
    &:not(:last-child) {
      margin-right: 0.5rem;
  }
}
}