.preloader.available {
  opacity: 0;
}

.preloader {
  background-color: #1b2430;
  width: 100%;
  height: 100%;
  position: absolute;
  opacity: 0.9;
  z-index: 9999;
}
.preloaderTwo {
  background-color: #ffffff;
  width: 100%;
  height: 100%;
  //position: absolute;
  opacity: 0.9;
  z-index: 9999;
}
.svgLoader {
  animation: spin 0.5s linear infinite;
}

.divLoader {
  width: 100%;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: auto;
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }

  100% {
    transform: rotate(360deg);
  }
}
